#include <mutex>
#include <stop_token>
#include <thread>

class FeedService {
public:
    FeedService()
        : worker_{[this](std::stop_token stop) { run(stop); }} {}

    long polls() const {
        std::lock_guard lock{mutex_};
        return polls_;
    }

private:
    void run(std::stop_token stop) {
        while (!stop.stop_requested()) {
            poll_once();
        }
    }

    void poll_once() {
        std::lock_guard lock{mutex_};
        ++polls_;
    }

    mutable std::mutex mutex_;
    long polls_ = 0;

    // Declared last on purpose: members are destroyed in reverse declaration
    // order, so ~jthread requests stop and joins while mutex_ and polls_ are
    // still alive. Declaring it first would destroy them under the worker.
    std::jthread worker_;
};

#include <random>
