// Two costs of thread_local: a dynamically initialized instance needs a
// per-thread guard check on access and runs its constructor once per thread
// (not once per process), and every live thread holds its own copy, so a
// worst-case-sized buffer costs worst_case x thread_count of memory.

int jittered_price(int price) {
    thread_local std::mt19937 engine{std::random_device{}()};
    std::uniform_int_distribution<int> jitter{-1, 1};
    return price + jitter(engine);
}

std::string& scratch_buffer() {
    thread_local std::string buffer;
    buffer.clear();          // reuse the capacity, drop the contents
    buffer.reserve(256);     // sized for typical work, not worst case
    return buffer;
}

