class TradeCounter {
public:
    void add_batch(long count) {
        std::lock_guard lock{mutex_};
        total_ += count;
    }

    long total() const {
        // Every access to guarded state follows the same policy. Locking the
        // writers but not the readers still leaves a data race.
        std::lock_guard lock{mutex_};
        return total_;
    }

private:
    mutable std::mutex mutex_;
    long total_ = 0;
};

void count_filled(TradeCounter& counter, const std::vector<int>& trades) {
    long local = 0;
    for (int quantity : trades) {
        if (quantity > 0) {
            ++local;
        }
    }

    counter.add_batch(local);  // one acquisition per batch
}

#include <mutex>
#include <string>

struct Account {
    // mutex guards balance, and only balance, for this account.
    int balance = 0;
    mutable std::mutex mutex;
};

std::string format_for_log(int balance);

bool transfer(Account& from, Account& to, int amount) {
    if (&from == &to) {
        return true;  // locking the same mutex twice would be undefined
    }

    // scoped_lock avoids hold-and-wait: it never blocks indefinitely on the
    // second mutex while retaining the first, so opposing callers cannot
    // form a wait cycle.
    std::scoped_lock lock{from.mutex, to.mutex};

    if (from.balance < amount) {
        return false;
    }

    from.balance -= amount;
    to.balance += amount;
    return true;
}

std::string snapshot_log(const Account& account) {
    int balance = 0;
    {
        std::lock_guard lock{account.mutex};
        balance = account.balance;  // copy out, then release
    }

    return format_for_log(balance);  // allocates and formats unlocked
}

