class ConfigStore {
public:
    std::string lookup(const std::string& key) const {
        std::shared_lock lock{mutex_};
        return values_.at(key);
    }

    void reload(std::unordered_map<std::string, std::string> next) {
        std::unique_lock lock{mutex_};
        values_ = std::move(next);
    }

private:
    // Justifying shared_mutex needs the read *duration*, not the read
    // percentage: every reader writes shared reader bookkeeping whose cache
    // line then bounces between cores. Only read sections long enough to
    // overlap usefully recover that cost, and only if writes stay rare
    // enough not to repeatedly exclude readers. Measure both against a
    // plain std::mutex before choosing.
    mutable std::shared_mutex mutex_;
    std::unordered_map<std::string, std::string> values_;
};

#include <condition_variable>
