class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : capacity_(capacity) {}

    void push(int value) {
        std::unique_lock lock{mutex_};
        not_full_.wait(lock, [this] {
            return items_.size() < capacity_;
        });

        items_.push(value);
        lock.unlock();          // publish first, then notify
        not_empty_.notify_one();
    }

    int pop() {
        std::unique_lock lock{mutex_};
        not_empty_.wait(lock, [this] {
            return !items_.empty();
        });

        int value = items_.front();
        items_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

private:
    // Two conditions, two condition variables. With one shared CV a
    // notify_one() after a pop could wake a blocked consumer instead of the
    // waiting producer; that consumer rechecks its predicate, finds the
    // queue empty, and parks again while the producer sleeps on. Correct but
    // wasteful at best, and it forces notify_all() to stay correct.
    std::mutex mutex_;
    std::condition_variable not_empty_;
    std::condition_variable not_full_;
    std::queue<int> items_;
    std::size_t capacity_;
};

#include <mutex>
#include <string>

struct Config {
    std::string endpoint;
    int venue_count = 0;
};

Config load_config();
void connect(const Config& config);

class Service {
public:
    void initialize() {
        // Exactly one invocation completes. Concurrent callers block until it
        // does, then observe its effects. If load_config() or connect()
        // throws, the exception propagates to that caller, the flag stays
        // unset, and a later call may try again.
        std::call_once(initialized_, [this] {
            config_ = load_config();
            connect(config_);
        });
    }

private:
    std::once_flag initialized_;
    Config config_{};
};

#include <cstddef>
#include <latch>
#include <thread>
#include <vector>

void prepare_worker(int id);
void measure_worker(int id);

void run_benchmark(int worker_count) {
    // A latch counts down to one event that happens once: 'every worker is
    // ready'. It stays open afterwards and cannot be reset, which is exactly
    // right for a start gate. If the workers had to rendezvous at the end of
    // every phase, that repeated boundary is std::barrier, which resets
    // itself (and can run a completion step) after each phase.
    std::latch start_gate{worker_count};

    std::vector<std::jthread> workers;
    workers.reserve(static_cast<std::size_t>(worker_count));

    for (int id = 0; id < worker_count; ++id) {
        workers.emplace_back([&start_gate, id] {
            prepare_worker(id);
            start_gate.arrive_and_wait();  // counts down, then waits for zero
            measure_worker(id);
        });
    }
}  // every jthread joins here

#include <condition_variable>
#include <functional>
#include <mutex>
#include <queue>
#include <stop_token>
#include <utility>

class ThreadPool {
public:
    void submit(std::function<void()> task) {
        {
            std::lock_guard lock{mutex_};
            tasks_.push(std::move(task));
        }
        ready_.notify_one();  // publish under the lock, notify after
    }

private:
    // Shutdown policy: DRAIN. A worker exits only once a stop has been
    // requested and no queued task remains, so already-submitted work still
    // runs. Discarding pending work is an equally valid policy, but the API
    // has to say which one it implements.
    void run(std::stop_token stop) {
        for (;;) {
            std::function<void()> task;
            {
                std::unique_lock lock{mutex_};
                ready_.wait(lock, stop, [this] {
                    return !tasks_.empty();
                });

                if (stop.stop_requested() && tasks_.empty()) {
                    return;
                }

                task = std::move(tasks_.front());  // move out under the lock
                tasks_.pop();
            }

            task();  // run with the mutex released
        }
    }

    std::mutex mutex_;
    std::condition_variable_any ready_;
    std::queue<std::function<void()>> tasks_;
};

#include <mutex>
#include <thread>

void update_guarded_pair();

// Fix 1: break CIRCULAR WAIT. scoped_lock acquires the set with a
// deadlock-avoidance algorithm, so no caller can hold one mutex while
// blocking indefinitely on the other. This does not address contention: a
// hot pair of mutexes can still form a lock convoy.
void update_ordered(std::mutex& first, std::mutex& second) {
    if (&first == &second) {
        std::lock_guard lock{first};
        update_guarded_pair();
        return;
    }

    std::scoped_lock lock{first, second};
    update_guarded_pair();
}

// Fix 2: break HOLD AND WAIT. The caller never waits for `second` while
// retaining `first`. This rules out deadlock but not LIVELOCK: two opposing
// callers can release and retry in lockstep forever, burning CPU while
// completing nothing. Production retry adds randomized backoff.
void update_try_lock(std::mutex& first, std::mutex& second) {
    if (&first == &second) {
        std::lock_guard lock{first};
        update_guarded_pair();
        return;
    }

    for (;;) {
        std::unique_lock first_lock{first};
        std::unique_lock second_lock{second, std::try_to_lock};

        if (second_lock.owns_lock()) {
            update_guarded_pair();
            return;
        }

        first_lock.unlock();
        std::this_thread::yield();
    }
}
